import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"《薛定谔的电话》—— Steam游戏催泪剧情","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/culture/schrodingers-phone.md","filePath":"topics/culture/schrodingers-phone.md"}'),n={name:"topics/culture/schrodingers-phone.md"};function s(l,t,d,h,i,p){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="《薛定谔的电话》——-steam游戏催泪剧情" tabindex="-1">《薛定谔的电话》—— Steam游戏催泪剧情 <a class="header-anchor" href="#《薛定谔的电话》——-steam游戏催泪剧情" aria-label="Permalink to &quot;《薛定谔的电话》—— Steam游戏催泪剧情&quot;">​</a></h1><blockquote><p>整理自：Steam游戏剧情解说</p></blockquote><hr><h2 id="世界观设定" tabindex="-1">世界观设定 <a class="header-anchor" href="#世界观设定" aria-label="Permalink to &quot;世界观设定&quot;">​</a></h2><p><strong>背景：</strong> 世界即将毁灭 <strong>主角：</strong> 玛丽——世间最后的倾听者 <strong>职责：</strong> 接听逝者的电话，帮助他们恢复记忆、完成未了的心愿</p><blockquote><p>在世界末日的废墟中，有一间电话亭。每一个打进来的电话，都是一个灵魂最后的执念。</p></blockquote><hr><h2 id="第一个故事-露西与威廉" tabindex="-1">第一个故事：露西与威廉 <a class="header-anchor" href="#第一个故事-露西与威廉" aria-label="Permalink to &quot;第一个故事：露西与威廉&quot;">​</a></h2><h3 id="人物关系" tabindex="-1">人物关系 <a class="header-anchor" href="#人物关系" aria-label="Permalink to &quot;人物关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>身份</th></tr></thead><tbody><tr><td>露西</td><td>母亲，因杀害债主入狱</td></tr><tr><td>威廉</td><td>露西的儿子，养父是约翰</td></tr><tr><td>约翰</td><td>露西的前夫，威廉的养父</td></tr></tbody></table><hr><h3 id="悲剧真相" tabindex="-1">悲剧真相 <a class="header-anchor" href="#悲剧真相" aria-label="Permalink to &quot;悲剧真相&quot;">​</a></h3><p><strong>第一层误解：</strong></p><blockquote><p>露西在狱中假扮邻居打电话给儿子，却被前夫约翰欺骗。威廉从此误以为——妈妈不爱他。</p></blockquote><p><strong>第二层真相：</strong></p><blockquote><p>约翰为了独占威廉，逼迫露西隐瞒身份，阻止母子相见。</p></blockquote><p><strong>第三层牺牲：</strong></p><blockquote><p>露西替儿子顶罪入狱，牺牲了自己的一生，只为保护儿子的未来。</p></blockquote><hr><h3 id="细节碎片" tabindex="-1">细节碎片 <a class="header-anchor" href="#细节碎片" aria-label="Permalink to &quot;细节碎片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>碎片</th><th>含义</th></tr></thead><tbody><tr><td>望远镜</td><td>威廉梦想成为天文学家，视望远镜为珍宝，为了保护它与债主发生冲突</td></tr><tr><td>最后一通电话</td><td>露西本想告诉儿子真相，却被约翰拦截</td></tr><tr><td>恢复记忆</td><td>玛丽引导露西恢复全部记忆，直面真相</td></tr></tbody></table><hr><h2 id="主题解读" tabindex="-1">主题解读 <a class="header-anchor" href="#主题解读" aria-label="Permalink to &quot;主题解读&quot;">​</a></h2><h3 id="_1-爱是永不熄灭的执念" tabindex="-1">1. 爱是永不熄灭的执念 <a class="header-anchor" href="#_1-爱是永不熄灭的执念" aria-label="Permalink to &quot;1. 爱是永不熄灭的执念&quot;">​</a></h3><p>露西用一生守护儿子，即使身陷囹圄、即使被误解、即使付出一切——</p><blockquote><p><strong>&quot;我没能陪你长大，但我用我的自由，换了你一辈子的平安。&quot;</strong></p></blockquote><hr><h3 id="_2-误解是世上最残忍的刀" tabindex="-1">2. 误解是世上最残忍的刀 <a class="header-anchor" href="#_2-误解是世上最残忍的刀" aria-label="Permalink to &quot;2. 误解是世上最残忍的刀&quot;">​</a></h3><p>威廉一生以为自己被抛弃，却不知道母亲正在狱中为他顶罪。</p><blockquote><p>约翰不是坏人，他只是爱得自私——他用&quot;保护&quot;的谎言，切断了母子之间最深的联结。</p></blockquote><hr><h3 id="_3-薛定谔的隐喻" tabindex="-1">3. 薛定谔的隐喻 <a class="header-anchor" href="#_3-薛定谔的隐喻" aria-label="Permalink to &quot;3. 薛定谔的隐喻&quot;">​</a></h3><p>游戏名&quot;薛定谔的电话&quot;暗含一个残忍的量子隐喻：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在电话接通之前——</span></span>
<span class="line"><span>威廉不知道母亲爱他（叠加态）</span></span>
<span class="line"><span>露西不知道儿子是否怨恨她（叠加态）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>直到最后一通电话拨通，</span></span>
<span class="line"><span>叠加态才坍缩为确定的真相。</span></span></code></pre></div><hr><h3 id="_4-倾听者的意义" tabindex="-1">4. 倾听者的意义 <a class="header-anchor" href="#_4-倾听者的意义" aria-label="Permalink to &quot;4. 倾听者的意义&quot;">​</a></h3><p>玛丽不是救世主，她只是：</p><ul><li><strong>接住</strong>那些无处诉说的思念</li><li><strong>传递</strong>那些来不及说出口的话</li><li><strong>见证</strong>那些用一生守护的秘密</li></ul><hr><h2 id="催泪金句" tabindex="-1">催泪金句 <a class="header-anchor" href="#催泪金句" aria-label="Permalink to &quot;催泪金句&quot;">​</a></h2><ol><li><strong>&quot;妈妈想告诉你，我是你的妈妈。但是有人不让我说。&quot;</strong></li><li><strong>&quot;我用我的自由，换了你一辈子的平安。&quot;</strong></li><li><strong>&quot;孩子，妈妈从来没有不爱你。&quot;</strong></li></ol><hr><h2 id="与其他主题的连接" tabindex="-1">与其他主题的连接 <a class="header-anchor" href="#与其他主题的连接" aria-label="Permalink to &quot;与其他主题的连接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>连接点</th></tr></thead><tbody><tr><td>量子叠加态</td><td>游戏名本身即隐喻——真相在被说出之前，同时存在&quot;爱&quot;与&quot;不爱&quot;两种可能</td></tr><tr><td>地狱占星师</td><td>同样的故事结构——为了攀爬/守护而牺牲，最终发现失去的恰恰是最重要的</td></tr><tr><td>冰心诀</td><td>放下执念才能清明——露西的执念是&quot;让儿子知道真相&quot;，当真相揭开，她才真正解脱</td></tr></tbody></table><hr><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p><strong>这世上最深的爱，往往藏在最深的误解里。而电话那头的沉默，不是不爱——是在用一生等待一个被听见的机会。</strong></p></blockquote><hr><p><em>整理日期：2026-06-22</em></p>`,49)])])}const b=a(n,[["render",s]]);export{u as __pageData,b as default};
